head.script:
scwin.qa998Summary = null;
scwin.qa998RunSequence = 0;
scwin.qa998Counts = null;

scwin.waitForDone = function() {
    return new Promise(function(resolve, reject) {
        var started = Date.now();
        var timer = window.setInterval(function() {
            if (scwin.qa998Counts.done === 1) {
                window.clearInterval(timer);
                resolve();
            } else if (Date.now() - started > 10000) {
                window.clearInterval(timer);
                reject(new Error("Submission 요청이 완료되지 않았습니다."));
            }
        }, 25);
    });
};

scwin.qa998Callback = function(result, submission) {
    scwin.qa998Counts.callback += 1;
    scwin.qa998Counts.argsValid = !!(result && submission);
};

scwin.runTest = async function() {
    var id = "waea998Qa_" + Date.now() + "_" + (++scwin.qa998RunSequence);
    scwin.qa998Counts = { callback: 0, done: 0, argsValid: false };
    btn_run_all.setDisabled(true);
    tbx_overall.setValue("실행 중");
    tbx_result.setValue("Submission을 실행하고 callbackSubmitFunction 호출을 기다리고 있습니다...");

    try {
        $p.createSubmission({
            id: id,
            action: "WAEA_998_submission_callbackSubmitFunction_QA.xml",
            method: "get",
            mediatype: "application/xml",
            callbackSubmitFunction: "scwin.qa998Callback",
            submitDoneHandler: function() {
                scwin.qa998Counts.done += 1;
            }
        });
        $p.executeSubmission(id);
        await scwin.waitForDone();
        await new Promise(function(resolve) { window.setTimeout(resolve, 50); });

        var pass = scwin.qa998Counts.callback === 1 &&
            scwin.qa998Counts.done === 1 &&
            scwin.qa998Counts.argsValid === true;
        scwin.qa998Summary = {
            done: true,
            pass: pass,
            callbackCount: scwin.qa998Counts.callback,
            doneCount: scwin.qa998Counts.done,
            argsValid: scwin.qa998Counts.argsValid
        };
        tbx_overall.setValue(pass ? "PASS - callbackSubmitFunction 1회 실행" : "FAIL - 실행 결과를 확인하세요");
        tbx_result.setValue(
            "callbackSubmitFunction 실행 횟수: " + scwin.qa998Counts.callback + "\n" +
            "submitDoneHandler 실행 횟수: " + scwin.qa998Counts.done + "\n" +
            "콜백 인자 전달: " + (scwin.qa998Counts.argsValid ? "정상" : "비정상") + "\n\n" +
            "기대 결과: callbackSubmitFunction이 정확히 1회 실행됩니다."
        );
    } catch (error) {
        scwin.qa998Summary = {
            done: true,
            pass: false,
            error: error.stack || error.message || String(error)
        };
        tbx_overall.setValue("FAIL - 실행 오류");
        tbx_result.setValue(scwin.qa998Summary.error);
    } finally {
        btn_run_all.setDisabled(false);
    }
};

scwin.btn_run_all_onclick = function() {
    scwin.qa998Summary = null;
    scwin.runTest();
};

scwin.onpageload = function() {
    tbx_overall.setValue("대기 - 테스트 실행 버튼을 누르세요");
    tbx_result.setValue("확인 항목\ncreateSubmission()에 설정한 callbackSubmitFunction이 Submission 완료 시 1회 실행되는지 확인합니다.");
};
